using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameFrontEnd
{
 bool HeldDirectiveAckCase=>FlowCase=="dirheld-ack";
 int HeldDirectiveSlot=>FlowCase=="dirheld-original"?2:FlowCase=="dirheld-same"?0:1;
 TroopDispatch HeldDirectiveRoot()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.First(d=>d.Recipient==NewGameMilitary.UnitIdsFor(game!.Session.DiagnosticSnapshot())[HeldDirectiveSlot]);
 TroopReceipt HeldDirectiveInitial()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Single(r=>r.Id==HeldDirectiveRoot().Id);
 UnitHeldTransfer OriginalTransfer()=>game!.Session.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.First(t=>t.Action==NewMilitaryAction.DeliverHeldUnitDirective);
 UnitDirectiveLateOutcome OriginalLate()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Holding!.Outcomes.Single(f=>f.Transfer==OriginalTransfer().Id);
 TroopDispatch HeldDirectiveCopy()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last(d=>d.Message==HeldDirectiveRoot().Message);
 TroopReceipt HeldCopyReceipt()=>game!.Session.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Single(r=>r.Id==HeldDirectiveCopy().Id);
 void OneDirectiveRootEffect(){var w=game!.Session.DiagnosticSnapshot();var x=w.NewMilitary!.UnitDirective!;Check(!HeldDirectiveInitial().Delivered,"late receipt never rewrites initial actual loss");Check(w.Messaging.Receipts.Count(r=>r.MessageId==HeldDirectiveRoot().Message)==1,"common formal original receipt remains unique");Check(x.Effects.Count(e=>e.Outcome==UnitDirectiveOutcome.Applied)+x.Holding!.Outcomes.Count(e=>e.Outcome==UnitDirectiveOutcome.Applied)==1&&w.NewMilitary.Orders.Count(o=>o.Action==NewMilitaryAction.SendUnitDirective)==1,"actual held original and copy cause exactly one scoped effect");}
 async Task DirectiveHoldingStep(int n){await Frame();var s=game!.Session;
  if(n==0){game.SelectKnownMilitary(NewGameMilitary.UnitIdsFor(game!.Session.DiagnosticSnapshot())[HeldDirectiveSlot]);game.ChooseMilitary(NewMilitaryAction.RemoteRecall);game.Advance(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);game.Press("unit-directive-hold");Check(!game.ButtonEnabled("unit-directive-handoff"),"no paper is invented before real failed delivery returns");}
  if(n==1){game.Advance(HeldDirectiveRoot().DueAt);Check(!HeldDirectiveInitial().Delivered&&!game.ButtonEnabled("unit-directive-handoff"),"actual miss alone does not teleport original back to sender");}
  if(n==2){game.Advance(HeldDirectiveInitial().ReplyDueAt);game.Advance(Math.Max(s.Seconds,ArmyEnd()+2));Check(game.ButtonEnabled("unit-directive-handoff")&&NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),HeldDirectiveRoot().Id)!=null,"actual original and its carrier physically return within handover range");}
  if(n==3){if(FlowCase=="dirheld-copy"){game.Press("unit-directive-retry");game.Advance(HeldDirectiveCopy().DueAt);game.Press("unit-directive-handoff");Check(HeldDirectiveCopy().DueAt<OriginalTransfer().DueAt,"copied original really arrived before held original");}else if(FlowCase=="dirheld-original"){game.Press("unit-directive-handoff");game.Advance(s.Seconds+1);game.Press("unit-directive-retry");Check(OriginalTransfer().DueAt<HeldDirectiveCopy().DueAt,"held original really arrives before already dispatched copy");}else if(FlowCase=="dirheld-same"){game.Press("unit-directive-retry");game.Press("unit-directive-handoff");Check(OriginalTransfer().DueAt==HeldDirectiveCopy().DueAt,"real held original and copy share exact arrival tick");}else game.Press("unit-directive-handoff");Check(!game.ButtonEnabled("unit-directive-handoff"),"busy original carrier cannot be reused");}
  if(n==4){game.Advance(OriginalTransfer().DueAt);Check(OriginalLate().Received,"actual held original is formally handed to its own recipient");OneDirectiveRootEffect();}
  if(n==5){if(HeldDirectiveAckCase){var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());game.ExercisePersonalMove(new(a.X-40000,a.Y));game.Advance(OriginalLate().DueAt);var w=s.DiagnosticSnapshot();Check(!MessageFlow.Knows(w.Messaging,OriginalLate().ReplyMessage!,w.PlayerControl.Value)&&NewGameMilitary.HeldPapers(w,s.Seconds).Any(h=>h.Message==OriginalLate().ReplyMessage),"late ack misses moving person and stays actual held paper");}else{game.Advance(Math.Max(s.Seconds,HeldDirectiveCopy().DueAt)+1);Check(HeldCopyReceipt().Delivered,"copied original also really reaches post");OneDirectiveRootEffect();}}
  if(n==6){if(HeldDirectiveAckCase){game.Advance(Math.Max(s.Seconds,PersonEnd()+1));game.ExercisePersonalMove(OriginalLate().Destination);game.Advance(PersonEnd()+1);Check(NewGameMilitary.HeldAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.TakeHeldReply),"returning person can actually meet ack carrier");game.ChooseMilitary(NewMilitaryAction.TakeHeldReply);}else{game.Advance(Math.Max(OriginalLate().DueAt,HeldCopyReceipt().ReplyDueAt)+1);OneDirectiveRootEffect();Check(NewGameMilitary.UnitDirectiveOriginalStatus(s.DiagnosticSnapshot(),HeldDirectiveRoot().Id).Contains("同じ原本を重複実行せず"),"physically received reply explains original deduplication");}}
  if(n==7){if(HeldDirectiveAckCase){game.Advance(s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt+1);var w=s.DiagnosticSnapshot();Check(MessageFlow.Knows(w.Messaging,OriginalLate().ReplyMessage!,w.PlayerControl.Value)&&NewGameMilitary.UnitDirectiveOriginalStatus(w,HeldDirectiveRoot().Id).Contains("遅着返書"),"actual held ack handover restores knowledge");}else{game.Advance(s.Seconds+3);game.Press("rotate");}OneDirectiveRootEffect();}
  game.Refresh();Check(game.RecognitionModelsMatch(),"actual held-original 3D matches player recognition at"+n);game.Press("save");await WaitSave();
 }
 async Task BeginDirectiveHoldingContinuation(){for(int n=1;n<=7;n++)await MilitaryStep(n);for(int n=0;n<=4;n++)await RecognitionStep(n);for(int n=0;n<8;n++){await DirectiveHoldingStep(n);game!.SaveCheckpoint("dirheld"+n);await Capture("s"+n,true);}await Capture("final",true);}
 async Task RestoreDirectiveHolding(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,row=>row.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<8;n++){game!.LoadCheckpoint("dirheld"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"same physical paper/holder/root selection/3D after restore"+n);await Capture("restored-s"+n,true);for(int k=n+1;k<8;k++)await DirectiveHoldingStep(k);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same actual original and copy future after restore"+n);await Capture("continued-s"+n,true);GD.Print("UNIT_DIRECTIVE_HOLDING_RESTORED "+n);}}
 async Task RunDirectiveHoldingChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreDirectiveHolding();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--unit-directive-holding-film")){game!.LoadCheckpoint("dirheld4");var a=NewGameMilitary.Anchor(game.Session.DiagnosticSnapshot());game.ExercisePersonalMove(new(a.X-40000,a.Y));game.Press("auto");string dir=Path.Combine(TestOutput,"film",TestKey??"normal");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"held-"+n.ToString("D3")+".png"));}game.Press("pause");File.WriteAllText(Path.Combine(TestOutput,"film-manifest.json"),System.Text.Json.JsonSerializer.Serialize(new{Directory=Path.GetRelativePath(TestOutput,dir),Frames=180,Checkpoint=4,Action="person-leaves-late-ack-destination"}));}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("UNIT_DIRECTIVE_HOLDING_PASSED "+FlowCase);}
}
